#include <stdlib.h>
#include <string.h>
#include <stdio.h>
#include <pthread.h>

// IoT Device Message Handler - Multi-tenant MQTT broker backend
// Processes device telemetry and stores in tenant-partitioned PostgreSQL

typedef struct {
    char *payload;
    size_t payload_len;
    char *topic;
    int tenant_id;
    int ref_count;
    void (*cleanup)(void *);
} mqtt_message_t;

typedef struct {
    mqtt_message_t *current_msg;
    int device_id;
    char db_connstr[256];
    int is_processing;
} device_context_t;

static device_context_t *active_contexts[1024];
static pthread_mutex_t ctx_lock = PTHREAD_MUTEX_INITIALIZER;

void free_message(mqtt_message_t *msg) {
    if (msg) {
        free(msg->payload);
        free(msg->topic);
        free(msg);
    }
}

// Called from MQTT disconnect handler (separate thread)
void handle_device_disconnect(int device_id) {
    pthread_mutex_lock(&ctx_lock);
    device_context_t *ctx = active_contexts[device_id % 1024];
    if (ctx && ctx->device_id == device_id) {
        // Free the current message on disconnect
        free_message(ctx->current_msg);
        ctx->current_msg = NULL;
        // Note: we do NOT clear active_contexts entry here
        // because reconnection logic needs the context
    }
    pthread_mutex_unlock(&ctx_lock);
}

// Persist telemetry to database - uses parameterized query with tenant_id
int persist_telemetry(device_context_t *ctx, mqtt_message_t *msg) {
    // Connection uses SET app.current_tenant = tenant_id on connect
    // RLS policy: CREATE POLICY tenant_isolation ON telemetry
    //   USING (tenant_id = current_setting('app.current_tenant')::int)
    char query[512];
    snprintf(query, sizeof(query),
        "INSERT INTO telemetry (device_id, tenant_id, payload) VALUES (%d, %d, $1)",
        ctx->device_id, msg->tenant_id);
    // execute_parameterized(ctx->db_connstr, query, msg->payload, msg->payload_len);
    printf("Persisting: device=%d tenant=%d len=%zu\n",
        ctx->device_id, msg->tenant_id, msg->payload_len);
    return 0;
}

// Main message processing - called from worker thread pool
int process_device_message(int device_id, const char *raw_payload, size_t len) {
    pthread_mutex_lock(&ctx_lock);
    device_context_t *ctx = active_contexts[device_id % 1024];
    pthread_mutex_unlock(&ctx_lock);

    if (!ctx) return -1;

    // Allocate and populate message
    mqtt_message_t *msg = (mqtt_message_t *)malloc(sizeof(mqtt_message_t));
    msg->payload = (char *)malloc(len);
    memcpy(msg->payload, raw_payload, len);
    msg->payload_len = len;
    msg->topic = strdup("telemetry/v1");
    msg->tenant_id = ctx->device_id >> 16; // upper bits encode tenant
    msg->ref_count = 1;
    msg->cleanup = NULL;

    // Store reference in context (UAF: disconnect handler may free this)
    ctx->current_msg = msg;
    ctx->is_processing = 1;

    // Simulate async processing delay (window for race condition)
    // During this window, handle_device_disconnect can free ctx->current_msg
    // Then we use msg below which points to freed memory

    // --- RACE WINDOW START ---
    // Another thread calls handle_device_disconnect(device_id) here
    // which frees msg via ctx->current_msg
    // --- RACE WINDOW END ---

    // Use-after-free: msg may have been freed by disconnect handler
    // since ctx->current_msg == msg, and disconnect frees ctx->current_msg
    if (msg->payload_len > 0) {  // UAF read
        persist_telemetry(ctx, msg);  // UAF: reads msg->tenant_id, msg->payload
    }

    ctx->is_processing = 0;
    return 0;
}

// Device registration
device_context_t *register_device(int device_id, const char *connstr) {
    device_context_t *ctx = (device_context_t *)calloc(1, sizeof(device_context_t));
    ctx->device_id = device_id;
    strncpy(ctx->db_connstr, connstr, sizeof(ctx->db_connstr) - 1);
    ctx->current_msg = NULL;
    ctx->is_processing = 0;

    pthread_mutex_lock(&ctx_lock);
    active_contexts[device_id % 1024] = ctx;
    pthread_mutex_unlock(&ctx_lock);
    return ctx;
}

int main() {
    register_device(0x00050001, "host=db.internal dbname=iot");
    const char *payload = "{\"temp\": 22.5, \"humidity\": 45}";
    process_device_message(0x00050001, payload, strlen(payload));
    return 0;
}
